using CarShopApi.Services;
using CarShopApi.Controllers.Dtos;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;
using Microsoft.AspNetCore.Authorization;

namespace CarShopApi.Controllers;

[ApiController]
[Route("api/v1/[controller]")]

public class CarController(CarService service) : ControllerBase
{
    private readonly CarService _service = service;

    [HttpGet()]
    [Authorize(Roles = "Admin,Vendor")] 
    [ProducesResponseType( typeof(IEnumerable<Car>) ,StatusCodes.Status200OK)]
    public async Task<IActionResult> GetAll()
    {
        return Ok(await _service.GetAllAsync());
    }

    [HttpPut()]
    [Authorize(Roles = "Admin")]
    [ProducesResponseType( typeof(Car) ,StatusCodes.Status200OK)]
    public async Task<IActionResult> CreateOrUpdate([FromBody] CreateOrUpdateCarDto carDto)
    {
        return Ok(await _service.CreateOrUpdateAsync(carDto));
    }

    [HttpDelete("{id}")]
    [Authorize(Roles = "Admin")]
    public async Task<IActionResult> Delete(int id)
    {
        var deleted = await _service.DeleteAsync(id);
        if (deleted)
        {
            return Ok();
        }
        return NotFound();
    }
}

using CarShopApi.Services;
using CarShopApi.Controllers.Dtos;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;
using Microsoft.AspNetCore.Authorization;

namespace CarShopApi.Controllers;

[ApiController]
[Route("api/v1/[controller]")]
public class CarController(CarService service) : ControllerBase
{
    private readonly CarService _service = service;

    [HttpGet]
    [Authorize(Roles = "Admin,Vendor")] 
    [ProducesResponseType(typeof(IEnumerable<Car>), StatusCodes.Status200OK)]
    public async Task<IActionResult> GetAll()
    {
        return Ok(await _service.GetAllAsync());
    }

    [HttpGet("{id}")]
    [Authorize(Roles = "Admin,Vendor")]
    [ProducesResponseType(typeof(Car), StatusCodes.Status200OK)]
    [ProducesResponseType(StatusCodes.Status404NotFound)]
    public async Task<IActionResult> GetById(long id)
    {
        var car = await _service.GetByIdAsync(id);

        if (car == null)
        {
            return NotFound();
        }

        return Ok(car);
    }

    [HttpPost]
    [Authorize(Roles = "Admin")]
    [ProducesResponseType(typeof(Car), StatusCodes.Status201Created)]
    [ProducesResponseType(StatusCodes.Status400BadRequest)]
    public async Task<IActionResult> Create([FromBody] CreateOrUpdateCarDto carDto)
    {
        try
        {
            var createdCar = await _service.CreateAsync(carDto);
            return CreatedAtAction(nameof(GetById), new { id = createdCar.Id }, createdCar);
        }
        catch (Exception ex)
        {
            return BadRequest(new { message = ex.Message });
        }
    }

    [HttpPut("{id}")]
    [Authorize(Roles = "Admin")]
    [ProducesResponseType(typeof(Car), StatusCodes.Status200OK)]
    [ProducesResponseType(StatusCodes.Status404NotFound)]
    public async Task<IActionResult> Update(long id, [FromBody] CreateOrUpdateCarDto carDto)
    {
        var updatedCar = await _service.UpdateAsync(id, carDto);

        if (updatedCar == null)
        {
            return NotFound();
        }

        return Ok(updatedCar);
    }

    [HttpDelete("{id}")]
    [Authorize(Roles = "Admin")]
    [ProducesResponseType(StatusCodes.Status204NoContent)]
    [ProducesResponseType(StatusCodes.Status404NotFound)]
    public async Task<IActionResult> Delete(long id)
    {
        var deleted = await _service.DeleteAsync(id);

        if (!deleted)
        {
            return NotFound();
        }

        return NoContent();
    }
}

using Microsoft.EntityFrameworkCore;
using CarShopApi.Controllers.Dtos;
using CarShopApi.Models;

namespace CarShopApi.Services;

public class CarService(AppDbContext db)
{
    private readonly AppDbContext _db = db;

    public async Task<List<Car>> GetAllAsync()
    {
        return await _db.Cars.Include(e => e.Images).ToListAsync();
    }

    public async Task<Car?> GetByIdAsync(long id)
    {
        return await _db.Cars.Where(e => e.Id == id).FirstOrDefaultAsync();
    }

    public async Task<Car?> CreateOrUpdateAsync(CreateOrUpdateCarDto carDto)
    {
        var transact = await _db.Database.BeginTransactionAsync();
        try
        {
            Car car;


            if (carDto.Id.HasValue)
            {
                var existingCar = await _db.Cars
                    .Include(c => c.Images)
                    .FirstOrDefaultAsync(e => e.Id == carDto.Id);

                if (existingCar != null)
                {
                    existingCar.New = carDto.New;
                    existingCar.Brand = carDto.Brand;
                    existingCar.Model = carDto.Model;
                    existingCar.Year = carDto.Year;
                    existingCar.Price = carDto.Price;
                    existingCar.Color = carDto.Color;
                    existingCar.Km = carDto.Km;
                    existingCar.Description = carDto.Description;

                    await _db.SaveChangesAsync();
                    await ProcessImages(existingCar, carDto.Images);
                    await transact.CommitAsync();
                    return existingCar;
                }
            }


            car = new Car
            {
                New = carDto.New,
                Brand = carDto.Brand,
                Model = carDto.Model,
                Year = carDto.Year,
                Price = carDto.Price,
                Color = carDto.Color,
                Km = carDto.Km,
                Description = carDto.Description
            };

            await _db.Cars.AddAsync(car);
            await _db.SaveChangesAsync();
            await ProcessImages(car, carDto.Images);

            await transact.CommitAsync();
            return car;
        }
        catch
        {
            await transact.RollbackAsync();
            throw;
        }
    }

    private async Task ProcessImages(Car car, IList<CreateOrUpdateCarImageDto> imageDtos)
    {
        foreach (var imageDto in imageDtos)
        {
            if (imageDto.Id.HasValue)
            {
                var existingImage = await _db.CarImages
                    .FirstOrDefaultAsync(i => i.Id == imageDto.Id && i.CarId == car.Id);

                if (existingImage != null)
                {
                    existingImage.Url = imageDto.Url;
                    await _db.SaveChangesAsync();
                    continue;
                }
            }


            var newImage = new CarImage
            {
                Url = imageDto.Url,
                CarId = car.Id ?? 0
            };

            await _db.CarImages.AddAsync(newImage);
            await _db.SaveChangesAsync();
        }
    }

    public async Task<bool> DeleteAsync(int id)
    {
        var car = await GetByIdAsync(id);
        if (car == null)
        {
            return false;
        }

        _db.Cars.Remove(car);
        await _db.SaveChangesAsync();
        return true;
    }
}

using Microsoft.EntityFrameworkCore;
using CarShopApi.Controllers.Dtos;
using CarShopApi.Models;

namespace CarShopApi.Services;

public class CarService(AppDbContext db)
{
    private readonly AppDbContext _db = db;

    public async Task<List<Car>> GetAllAsync()
    {
        return await _db.Cars.Include(e => e.Images).ToListAsync();
    }

    public async Task<Car?> GetByIdAsync(long id)
    {
        return await _db.Cars
            .Include(e => e.Images)
            .FirstOrDefaultAsync(e => e.Id == id);
    }

    public async Task<Car> CreateAsync(CreateOrUpdateCarDto carDto)
    {
        var transact = await _db.Database.BeginTransactionAsync();
        try
        {
            var car = new Car
            {
                New = carDto.New,
                Brand = carDto.Brand,
                Model = carDto.Model,
                Year = carDto.Year,
                Price = carDto.Price,
                Color = carDto.Color,
                Km = carDto.Km,
                Description = carDto.Description
            };

            await _db.Cars.AddAsync(car);
            await _db.SaveChangesAsync();
            await ProcessImages(car, carDto.Images);

            await transact.CommitAsync();
            return car;
        }
        catch
        {
            await transact.RollbackAsync();
            throw;
        }
    }

    public async Task<Car?> UpdateAsync(long id, CreateOrUpdateCarDto carDto)
    {
        var transact = await _db.Database.BeginTransactionAsync();
        try
        {
            var existingCar = await _db.Cars
                .Include(c => c.Images)
                .FirstOrDefaultAsync(e => e.Id == id);

            if (existingCar == null)
            {
                await transact.RollbackAsync();
                return null;
            }

            existingCar.New = carDto.New;
            existingCar.Brand = carDto.Brand;
            existingCar.Model = carDto.Model;
            existingCar.Year = carDto.Year;
            existingCar.Price = carDto.Price;
            existingCar.Color = carDto.Color;
            existingCar.Km = carDto.Km;
            existingCar.Description = carDto.Description;

            await _db.SaveChangesAsync();
            await ProcessImages(existingCar, carDto.Images);
            await transact.CommitAsync();
            return existingCar;
        }
        catch
        {
            await transact.RollbackAsync();
            throw;
        }
    }

    private async Task ProcessImages(Car car, IList<CreateOrUpdateCarImageDto> imageDtos)
    {
        foreach (var imageDto in imageDtos)
        {
            if (imageDto.Id.HasValue)
            {
                var existingImage = await _db.CarImages
                    .FirstOrDefaultAsync(i => i.Id == imageDto.Id && i.CarId == car.Id);

                if (existingImage != null)
                {
                    existingImage.Url = imageDto.Url;
                    await _db.SaveChangesAsync();
                    continue;
                }
            }

            var newImage = new CarImage
            {
                Url = imageDto.Url,
                CarId = car.Id ?? 0
            };

            await _db.CarImages.AddAsync(newImage);
            await _db.SaveChangesAsync();
        }
    }

    public async Task<bool> DeleteAsync(long id)
    {
        var car = await GetByIdAsync(id);
        if (car == null)
        {
            return false;
        }

        _db.Cars.Remove(car);
        await _db.SaveChangesAsync();
        return true;
    }
}
